/**
 * Pricing 2 Component
 *
 * Source: https://tailark.com/preview/dusk/pricing/two
 * License: Free Tier
 * Adapted from: Tailark
 *
 * Modifications:
 * - Integrated with PayloadCMS block system
 * - Replaced hardcoded content with dynamic props
 */


import { Check } from "lucide-react";
import Link from "next/link";

import type { Pricing_2_Block } from "~/payload-types";

import { cn } from "@/registry/default/utils";
import { Button } from "@/registry/ui/button";

export * from "./config";

export default function Pricing2(props: NonNullable<Pricing_2_Block>) {
	return (
		<section className="py-16 md:py-32">
			<div className="mx-auto max-w-6xl px-6">
				<div className="mx-auto max-w-2xl space-y-6 text-center">
					<h1 className="text-center text-4xl font-semibold lg:text-5xl">
						{props?.header ?? ""}
					</h1>
					<p>{props?.subheader ?? ""}</p>
				</div>

				<div className="mt-8 grid gap-6 md:mt-20 md:grid-cols-3">
					{(props?.tiers ?? []).map((tier, index) => (
						<PricingCard key={`pricing-2-tier-${index}`} tier={tier} />
					))}
				</div>
			</div>
		</section>
	);
}

function PricingCard({
	tier,
}: {
	tier: NonNullable<Pricing_2_Block["tiers"]>[number];
}) {
	if (!tier) {
		return null;
	}

	return (
		<div className="relative flex flex-col rounded-xl border bg-muted shadow-sm">
			{tier.isPopular && (
				<span className="absolute inset-x-0 -top-3 mx-auto flex h-6 w-fit items-center rounded-full bg-linear-to-br/increasing from-purple-400 to-amber-300 px-3 py-1 text-xs font-medium text-amber-950">
					Popular
				</span>
			)}

			<div className="flex flex-col gap-1.5 p-6">
				<h3 className="font-medium leading-none tracking-tight">{tier.name}</h3>
				<span className="my-3 block text-2xl font-semibold">
					${tier.price} / {tier.period}
				</span>
				{tier.description && (
					<p className="text-sm text-muted-foreground">{tier.description}</p>
				)}
			</div>

			<div className="space-y-4 p-6 pt-0">
				<hr className="border-dashed" />
				<ul className="list-outside space-y-3 text-sm">
					{(tier.features ?? []).map((feature, idx) => (
						<li
							className="flex items-center gap-2"
							key={`pricing-2-tier-${tier.name}-feature-${idx}`}
						>
							<Check className="size-3" />
							{feature.text}
						</li>
					))}
				</ul>
			</div>

			<div className="mt-auto flex items-center p-6 pt-0">
				<Button
					asChild
					className="w-full"
					variant={tier.isPopular ? "default" : "outline"}
				>
					<Link href={tier.buttonHref ?? ""}>{tier.buttonText}</Link>
				</Button>
			</div>
		</div>
	);
}

import type { Block } from "payload";

import {
	BLOCK_GROUP_PRICING,
	BLOCK_SLUG_PRICING_2,
} from "@/registry/default/lib/constants/blocks";
import descriptionField from "@/registry/default/lib/fields/description/config";
import headerField from "@/registry/default/lib/fields/header/config";
import subHeaderField from "@/registry/default/lib/fields/subheader/config";

export const Pricing_2_Block: Block = {
	slug: BLOCK_SLUG_PRICING_2,
	admin: {
		group: BLOCK_GROUP_PRICING,
	},
	fields: [
		headerField({
			defaultValue: "Pricing that Scales with You",
			required: false,
		}),
		subHeaderField({
			defaultValue: "Choose the perfect plan for your needs",
			required: false,
		}),
		{
			name: "tiers",
			type: "array",
			defaultValue: [
				{
					name: "Starter",
					description: "Perfect for small teams getting started",
					isPopular: false,
					price: 29,
					period: "mo",
					buttonText: "Get Started",
					buttonHref: "/signup",
					features: [
						{ text: "Up to 5 team members" },
						{ text: "10GB storage" },
						{ text: "Basic analytics" },
						{ text: "Email support" },
						{ text: "Core features" },
					],
				},
				{
					name: "Professional",
					description: "For growing teams with advanced needs",
					isPopular: true,
					price: 79,
					period: "mo",
					buttonText: "Get Started",
					buttonHref: "/signup",
					features: [
						{ text: "Up to 20 team members" },
						{ text: "100GB storage" },
						{ text: "Advanced analytics" },
						{ text: "Priority support" },
						{ text: "All features included" },
						{ text: "Custom integrations" },
					],
				},
				{
					name: "Enterprise",
					description: "For large organizations with custom requirements",
					isPopular: false,
					price: 199,
					period: "mo",
					buttonText: "Contact Sales",
					buttonHref: "/contact",
					features: [
						{ text: "Unlimited team members" },
						{ text: "Unlimited storage" },
						{ text: "Custom analytics" },
						{ text: "24/7 dedicated support" },
						{ text: "All features included" },
						{ text: "Custom integrations" },
						{ text: "SLA guarantee" },
						{ text: "Dedicated account manager" },
					],
				},
			],
			fields: [
				{
					name: "name",
					type: "text",
					label: "Plan Name",
					required: true,
				},
				descriptionField({
					defaultValue: "Per editor",
					required: false,
				}),
				{
					name: "isPopular",
					type: "checkbox",
					defaultValue: false,
					label: "Mark as Popular",
				},
				{
					name: "price",
					type: "number",
					defaultValue: 0,
					label: "Price",
					required: true,
				},
				{
					name: "period",
					type: "text",
					defaultValue: "mo",
					label: "Billing Period",
				},
				{
					name: "buttonText",
					type: "text",
					defaultValue: "Get Started",
					label: "Button Text",
					required: true,
				},
				{
					name: "buttonHref",
					type: "text",
					defaultValue: "",
					label: "Button Link",
					required: true,
				},
				{
					name: "features",
					type: "array",
					fields: [
						{
							name: "text",
							type: "text",
							required: true,
						},
					],
					maxRows: 15,
					minRows: 1,
				},
			],
			label: {
				plural: "Pricing Tiers",
				singular: "Pricing Tier",
			},
			maxRows: 4,
			minRows: 0,
		},
	],
	interfaceName: "Pricing_2_Block",
	labels: {
		plural: "Pricing 2's",
		singular: "Pricing 2",
	},
};
